/**
 * The outcome of `decide`.
 */
public struct Verdict: Equatable, Hashable {
    /**
     * How the phone answers.
     */
    public var asking: Asking
    /**
     * Confirmation level 1 to 3.
     */
    public var level: UInt8
    /**
     * The request kind.
     */
    public var kind: RequestKind
    /**
     * Buttons, in order.
     */
    public var options: [ReplyOption]
    /**
     * The decision to seal when `asking` is `Automatic`.
     */
    public var automatic: Decision?
    /**
     * The refusal when `asking` is `Refused`.
     */
    public var refuse: RefuseReason?
    /**
     * Where the phone is, for the reply.
     */
    public var place: Place
    /**
     * Level 2 and 3: the number match comes first.
     */
    public var needsNumber: Bool
    /**
     * Level 2 and 3: biometrics (strong, no device credential).
     */
    public var needsBiometrics: Bool
    /**
     * Level 2 without usable biometrics (or after an enrolment change): two words from the card.
     */
    public var needsCardWords: Bool
    /**
     * The plan or object list is shown.
     */
    public var showsPlan: Bool
    /**
     * Seconds the approval waits (level 3 away from a trusted place).
     */
    public var delaySecs: UInt32
    /**
     * An `open` from an agent with no answer: "Allow for this session" also remembers.
     */
    public var agentFirstUse: Bool
    /**
     * `open` would answer by itself at the current place (the card's last line).
     */
    public var answersByItselfHere: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * How the phone answers.
         */asking: Asking, 
        /**
         * Confirmation level 1 to 3.
         */level: UInt8, 
        /**
         * The request kind.
         */kind: RequestKind, 
        /**
         * Buttons, in order.
         */options: [ReplyOption], 
        /**
         * The decision to seal when `asking` is `Automatic`.
         */automatic: Decision?, 
        /**
         * The refusal when `asking` is `Refused`.
         */refuse: RefuseReason?, 
        /**
         * Where the phone is, for the reply.
         */place: Place, 
        /**
         * Level 2 and 3: the number match comes first.
         */needsNumber: Bool, 
        /**
         * Level 2 and 3: biometrics (strong, no device credential).
         */needsBiometrics: Bool, 
        /**
         * Level 2 without usable biometrics (or after an enrolment change): two words from the card.
         */needsCardWords: Bool, 
        /**
         * The plan or object list is shown.
         */showsPlan: Bool, 
        /**
         * Seconds the approval waits (level 3 away from a trusted place).
         */delaySecs: UInt32, 
        /**
         * An `open` from an agent with no answer: "Allow for this session" also remembers.
         */agentFirstUse: Bool, 
        /**
         * `open` would answer by itself at the current place (the card's last line).
         */answersByItselfHere: Bool) {
        self.asking = asking
        self.level = level
        self.kind = kind
        self.options = options
        self.automatic = automatic
        self.refuse = refuse
        self.place = place
        self.needsNumber = needsNumber
        self.needsBiometrics = needsBiometrics
        self.needsCardWords = needsCardWords
        self.showsPlan = showsPlan
        self.delaySecs = delaySecs
        self.agentFirstUse = agentFirstUse
        self.answersByItselfHere = answersByItselfHere
    }

    

    
}

