/**
 * Failures of the app rules and the local database.
 */
public 
enum AppError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The local database failed.
     */
    case Storage(
        /**
         * What failed (no secrets).
         */msg: String
    )
    /**
     * State bytes that do not decode.
     */
    case Decode
    /**
     * State written by a newer app.
     */
    case NewerVersion
    /**
     * No such record.
     */
    case NotFound
    /**
     * A value outside its allowed range.
     */
    case Invalid(
        /**
         * Which value.
         */msg: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension AppError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAppError: FfiConverterRustBuffer {
    typealias SwiftType = AppError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AppError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Storage(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Decode
        case 3: return .NewerVersion
        case 4: return .NotFound
        case 5: return .Invalid(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AppError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Storage(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case .Decode:
            writeInt(&buf, Int32(2))
        
        
        case .NewerVersion:
            writeInt(&buf, Int32(3))
        
        
        case .NotFound:
            writeInt(&buf, Int32(4))
        
        
        case let .Invalid(msg):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(msg, into: &buf)
            
        }
    }
}


