/**
 * A change to the relay state.
 */

public enum Event: Equatable, Hashable {
    
    /**
     * A new pairing. `replaces` moves the old machine's records to it and removes it.
     * Without `replaces`, machines with the same name show their tags.
     */
    case pairMachine(
        /**
         * The machine.
         */machine: Machine, 
        /**
         * Key of the machine it replaces.
         */replaces: String?
    )
    /**
     * Unpaired (tombstone). Its history and inventory stay.
     */
    case unpairMachine(
        /**
         * Key.
         */key: String
    )
    /**
     * Nickname, 1 to 40 characters; `None` removes it.
     */
    case setNickname(
        /**
         * Key.
         */key: String, 
        /**
         * Nickname.
         */nickname: String?
    )
    /**
     * The relay's machine list: `lastSeen` per machine.
     */
    case machinesListed(
        /**
         * (key, lastSeen) pairs.
         */seen: [MachineSeen]
    )
    /**
     * An answer to remember.
     */
    case rememberAnswer(
        /**
         * The answer.
         */answer: RememberedAnswer
    )
    /**
     * Remove an answer.
     */
    case removeAnswer(
        /**
         * Agent.
         */agent: String, 
        /**
         * Key name.
         */keyName: String, 
        /**
         * Repository id.
         */repoId: String
    )
    /**
     * A new trusted place.
     */
    case addPlace(
        /**
         * The place.
         */place: TrustedPlace
    )
    /**
     * Rename a place.
     */
    case renamePlace(
        /**
         * Id.
         */id: String, 
        /**
         * Name.
         */name: String
    )
    /**
     * Remove a place.
     */
    case removePlace(
        /**
         * Id.
         */id: String
    )
    /**
     * The words facts.
     */
    case setWords(
        /**
         * Facts.
         */words: WordsInfo
    )
    /**
     * Backups.
     */
    case setSettings(
        /**
         * Settings.
         */settings: Settings
    )
    /**
     * A report of a level 3 action.
     */
    case addReport(
        /**
         * The report.
         */report: HandbackReport
    )
    /**
     * After a download: the merge of the local and the relay state.
     */
    case mergeRemote(
        /**
         * The relay's state.
         */remote: State
    )
    /**
     * Delete my relay data: every machine is gone from the phone.
     */
    case forgetMachines





}

#if compiler(>=6)
extension Event: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeEvent: FfiConverterRustBuffer {
    typealias SwiftType = Event

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Event {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .pairMachine(machine: try FfiConverterTypeMachine.read(from: &buf), replaces: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 2: return .unpairMachine(key: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .setNickname(key: try FfiConverterString.read(from: &buf), nickname: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 4: return .machinesListed(seen: try FfiConverterSequenceTypeMachineSeen.read(from: &buf)
        )
        
        case 5: return .rememberAnswer(answer: try FfiConverterTypeRememberedAnswer.read(from: &buf)
        )
        
        case 6: return .removeAnswer(agent: try FfiConverterString.read(from: &buf), keyName: try FfiConverterString.read(from: &buf), repoId: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .addPlace(place: try FfiConverterTypeTrustedPlace.read(from: &buf)
        )
        
        case 8: return .renamePlace(id: try FfiConverterString.read(from: &buf), name: try FfiConverterString.read(from: &buf)
        )
        
        case 9: return .removePlace(id: try FfiConverterString.read(from: &buf)
        )
        
        case 10: return .setWords(words: try FfiConverterTypeWordsInfo.read(from: &buf)
        )
        
        case 11: return .setSettings(settings: try FfiConverterTypeSettings.read(from: &buf)
        )
        
        case 12: return .addReport(report: try FfiConverterTypeHandbackReport.read(from: &buf)
        )
        
        case 13: return .mergeRemote(remote: try FfiConverterTypeState.read(from: &buf)
        )
        
        case 14: return .forgetMachines
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Event, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .pairMachine(machine,replaces):
            writeInt(&buf, Int32(1))
            FfiConverterTypeMachine.write(machine, into: &buf)
            FfiConverterOptionString.write(replaces, into: &buf)
            
        
        case let .unpairMachine(key):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(key, into: &buf)
            
        
        case let .setNickname(key,nickname):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(key, into: &buf)
            FfiConverterOptionString.write(nickname, into: &buf)
            
        
        case let .machinesListed(seen):
            writeInt(&buf, Int32(4))
            FfiConverterSequenceTypeMachineSeen.write(seen, into: &buf)
            
        
        case let .rememberAnswer(answer):
            writeInt(&buf, Int32(5))
            FfiConverterTypeRememberedAnswer.write(answer, into: &buf)
            
        
        case let .removeAnswer(agent,keyName,repoId):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(agent, into: &buf)
            FfiConverterString.write(keyName, into: &buf)
            FfiConverterString.write(repoId, into: &buf)
            
        
        case let .addPlace(place):
            writeInt(&buf, Int32(7))
            FfiConverterTypeTrustedPlace.write(place, into: &buf)
            
        
        case let .renamePlace(id,name):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(id, into: &buf)
            FfiConverterString.write(name, into: &buf)
            
        
        case let .removePlace(id):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .setWords(words):
            writeInt(&buf, Int32(10))
            FfiConverterTypeWordsInfo.write(words, into: &buf)
            
        
        case let .setSettings(settings):
            writeInt(&buf, Int32(11))
            FfiConverterTypeSettings.write(settings, into: &buf)
            
        
        case let .addReport(report):
            writeInt(&buf, Int32(12))
            FfiConverterTypeHandbackReport.write(report, into: &buf)
            
        
        case let .mergeRemote(remote):
            writeInt(&buf, Int32(13))
            FfiConverterTypeState.write(remote, into: &buf)
            
        
        case .forgetMachines:
            writeInt(&buf, Int32(14))
        
        }
    }
}


