    }

    public static func write(_ value: LocalEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .setDay(day):
            writeInt(&buf, Int32(1))
            FfiConverterTypeDayRecord.write(day, into: &buf)
            
        
        case let .setHold(hold):
            writeInt(&buf, Int32(2))
            FfiConverterTypeHold.write(hold, into: &buf)
            
        
        case let .clearHold(machine):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(machine, into: &buf)
            
        
        case let .putPlan(plan):
            writeInt(&buf, Int32(4))
            FfiConverterTypePlanApprovalRecord.write(plan, into: &buf)
            
        
        case let .putDelayed(action):
            writeInt(&buf, Int32(5))
            FfiConverterTypeDelayedAction.write(action, into: &buf)
            
        
        case let .removeDelayed(id):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .setDevice(device):
            writeInt(&buf, Int32(7))
            FfiConverterTypeDeviceInfo.write(device, into: &buf)
            
        
        case let .setOnboardingStep(step):
            writeInt(&buf, Int32(8))
            FfiConverterUInt32.write(step, into: &buf)
            
        
        case .agentNoteShown:
            writeInt(&buf, Int32(9))
        
        
        case let .suppressCandidate(id):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .setLeave(step,skipped):
            writeInt(&buf, Int32(11))
            FfiConverterUInt32.write(step, into: &buf)
            FfiConverterSequenceString.write(skipped, into: &buf)
            
        
        case let .synced(rev,uploaded):
            writeInt(&buf, Int32(12))
            FfiConverterUInt64.write(rev, into: &buf)
            FfiConverterBool.write(uploaded, into: &buf)
            
        }
    }
}


