/**
 * The buttons the card and the notification offer, in order.
 */

public enum ReplyOption: Equatable, Hashable {
    
    /**
     * "Allow for this session" (`Session`, or `Remember` when an agent's first use is merged).
     */
    case allowSession
    /**
     * "Allow" for `agent` (`Remember`) and `keys` (`Session`).
     */
    case allow
    /**
     * "Allow once" (`Once`).
     */
    case allowOnce
    /**
     * "Deny".
     */
    case deny
    /**
     * Level 2 and 3: confirm with biometrics (and the number, plan, delay before it).
     */
    case confirm





}

#if compiler(>=6)
extension ReplyOption: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeReplyOption: FfiConverterRustBuffer {
    typealias SwiftType = ReplyOption

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ReplyOption {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .allowSession
        
        case 2: return .allow
        
        case 3: return .allowOnce
        
        case 4: return .deny
        
        case 5: return .confirm
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ReplyOption, into buf: inout [UInt8]) {
        switch value {
        
        
        case .allowSession:
            writeInt(&buf, Int32(1))
        
        
        case .allow:
            writeInt(&buf, Int32(2))
        
        
        case .allowOnce:
            writeInt(&buf, Int32(3))
        
        
        case .deny:
            writeInt(&buf, Int32(4))
        
        
        case .confirm:
            writeInt(&buf, Int32(5))
        
        }
    }
}


